"use client";

import { AnimatePresence, motion, type Transition } from "motion/react";
import { memo } from "react";
import type { WeatherData } from "@/hooks/useWeather";
import { WithHover } from "../cursor/WithHover";
import { LottieWeatherIcon } from "../LottieWeatherIcon";
import { ScrambleTicker } from "../ScrambleTicker";

interface WeatherPillProps {
  hoveredId: string | null;
  layoutTransition: Transition;
  setHoveredId: (id: string | null) => void;
  tempUnitLabel: string;
  tempValue: number | null;
  toggleUnit: () => void;
  weather: WeatherData | null;
}

export const WeatherPill = memo(
  ({
    weather,
    tempValue,
    tempUnitLabel,
    toggleUnit,
    hoveredId,
    setHoveredId,
    layoutTransition,
  }: WeatherPillProps) => {
    return (
      <motion.div
        className="flex min-w-[8ch] items-center justify-center md:min-w-[12ch]"
        layout
        transition={layoutTransition}
      >
        <AnimatePresence initial={false} mode="wait">
          {weather ? (
            <WithHover>
              <motion.button
                aria-label="Toggle temperature unit"
                className="relative z-60 flex h-5 w-full cursor-pointer items-center justify-center gap-1.5 rounded-sm px-2 py-0.5 text-foreground transition-colors md:h-8 md:gap-2 md:px-3"
                key="weather"
                layout
                onClick={toggleUnit}
                onMouseEnter={() => setHoveredId("weather")}
                onMouseLeave={() => setHoveredId(null)}
                transition={layoutTransition}
              >
                {hoveredId === "weather" ? (
                  <motion.div
                    animate={{ opacity: 1 }}
                    className="absolute inset-0 -z-10 hidden rounded-sm bg-muted/40 md:block"
                    exit={{ opacity: 0 }}
                    initial={{ opacity: 0 }}
                    layoutId="pill-hover"
                    transition={{ type: "spring", stiffness: 400, damping: 30 }}
                  />
                ) : null}
                <LottieWeatherIcon
                  code={weather.weatherCode}
                  isNight={!weather.isDay}
                />

                <motion.div
                  className="flex items-center gap-0.5 font-semibold tabular-nums"
                  layout
                  transition={layoutTransition}
                >
                  <ScrambleTicker
                    layoutTransition={layoutTransition}
                    text={tempValue !== null ? String(tempValue) : ""}
                  />
                  <motion.span
                    className="text-[10px] uppercase tracking-wider opacity-50 md:text-xs"
                    layout
                    transition={layoutTransition}
                  >
                    {tempUnitLabel}
                  </motion.span>
                </motion.div>
              </motion.button>
            </WithHover>
          ) : (
            <motion.div
              animate={{ opacity: 1 }}
              className="flex h-5 w-full items-center justify-center gap-1.5 px-2 py-0.5 md:h-8 md:gap-2 md:px-3"
              exit={{ opacity: 0 }}
              initial={{ opacity: 0 }}
              key="skeleton"
              layout
              transition={layoutTransition}
            >
              <div className="h-4 w-4 animate-pulse rounded-full bg-muted-foreground/10 md:h-6 md:w-6" />
              <div className="h-3 w-6 animate-pulse rounded-sm bg-muted-foreground/10 md:h-4 md:w-8" />
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    );
  }
);

WeatherPill.displayName = "WeatherPill";

"use client";

import React, { useCallback } from "react";
import { type CursorType, useCursor } from "./Context";

interface WithHoverProps {
  children: React.ReactElement<{
    onMouseEnter?: (e: React.MouseEvent<HTMLElement>) => void;
    onMouseOver?: (e: React.MouseEvent<HTMLElement>) => void;
    onMouseLeave?: (e: React.MouseEvent<HTMLElement>) => void;
  }>;
  config?: {
    hoverOffset?: number;
    [key: string]: unknown;
  };
  type?: CursorType;
}

const DEFAULT_CONFIG: { hoverOffset: number; [key: string]: unknown } = {
  hoverOffset: 3,
};

export const WithHover: React.FC<WithHoverProps> = ({
  children,
  type = "block",
  config = DEFAULT_CONFIG,
}) => {
  const { setSelectedElement, removeSelectedElement } = useCursor();

  const handleMouseEnter = useCallback(
    (e: React.MouseEvent<HTMLElement>) => {
      const target = e.currentTarget;
      const result: {
        el: HTMLElement;
        type: CursorType;
        config: Record<string, unknown>;
      } = {
        el: target,
        type,
        config: { ...config },
      };

      if (type === "text") {
        const computed = window.getComputedStyle(target).fontSize;
        const baseSize = Number.parseFloat(computed.replace("px", ""));
        const scale = (config.scale as number) || 1;
        result.config.textSize = baseSize * scale;
      } else {
        // For block types, capture the border radius to ensure the cursor matches the element shape
        const computed = window.getComputedStyle(target);
        result.config.borderRadius = computed.borderRadius;
      }

      setSelectedElement(result);
    },
    [type, config, setSelectedElement]
  );

  const handleMouseLeave = useCallback(() => {
    removeSelectedElement();
  }, [removeSelectedElement]);

  // Get the only child
  const child = React.Children.only(children);

  return React.cloneElement(child, {
    onMouseEnter: (e: React.MouseEvent<HTMLElement>) => {
      handleMouseEnter(e);
      child.props.onMouseEnter?.(e);
    },
    onMouseOver: (e: React.MouseEvent<HTMLElement>) => {
      child.props.onMouseOver?.(e);
    },
    onMouseLeave: (e: React.MouseEvent<HTMLElement>) => {
      handleMouseLeave();
      child.props.onMouseLeave?.(e);
    },
  });
};

"use client";

import { motion, type Transition } from "motion/react";
import { type UseScrambleProps, useScramble } from "use-scramble";
import { cn } from "@/lib/utils";

interface ScrambleTickerProps {
  align?: "left" | "center" | "right";
  className?: string;
  layout?: boolean | "position" | "preserve-aspect";
  layoutTransition?: Transition;
  scrambleProps?: Partial<UseScrambleProps>;
  text: string;
}

/**
 * A reusable component that implements the "Ghost Text" strategy for use-scramble.
 * Reserves space invisibly to prevent layout jitter while the scramble reveal plays.
 */
export function ScrambleTicker({
  text,
  className,
  scrambleProps,
  align = "left",
  layoutTransition,
  layout = true,
}: ScrambleTickerProps) {
  const { ref } = useScramble({
    text,
    speed: 0.6,
    tick: 1,
    step: 1,
    scramble: 3,
    seed: 2,
    playOnMount: false,
    ...scrambleProps,
  });

  return (
    <motion.div
      className={cn(
        "relative inline-flex items-center overflow-hidden px-0.5",
        className
      )}
      layout={layout}
      transition={layoutTransition}
    >
      {/* Ghost text drives width/height and is the layout anchor */}
      <motion.span
        aria-hidden="true"
        className="pointer-events-none invisible select-none whitespace-nowrap opacity-0"
        layout={layout}
        transition={layoutTransition}
      >
        {text}
      </motion.span>

      {/* Scramble reveal is absolutely positioned over the ghost to prevent jitter */}
      <motion.span
        className={cn(
          "absolute inset-x-0.5 inset-y-0 flex items-center whitespace-nowrap",
          align === "left" && "justify-start",
          align === "center" && "justify-center",
          align === "right" && "justify-end"
        )}
        layout={layout}
        ref={ref}
        transition={layoutTransition}
      />
    </motion.div>
  );
}

