export function LottieWeatherIcon({
  code,
  isNight,
}: {
  code: number;
  isNight: boolean;
}) {
  const [animationData, setAnimationData] = useState<unknown>(null);
  const { resolvedTheme } = useTheme();
  const mounted = useMounted();

  useEffect(() => {
    const loadLottie = async () => {
      const mapping = weatherIcons[code] ?? weatherIcons[0];
      const filename = isNight ? mapping.night : mapping.day;

      const cached = lottieCache.get(filename);
      if (cached !== undefined) {
        setAnimationData(cached);
        return;
      }

      try {
        const response = await fetch(`/weather/line/lottie/${filename}`);
        if (!response.ok) {
          return;
        }
        const data = (await response.json()) as unknown;
        lottieCache.set(filename, data);
        setAnimationData(data);
      } catch (error) {
        console.error("Failed to load weather icon:", filename, error);
      }
    };

    loadLottie();
  }, [code, isNight]);

  // In light mode, the icons (especially clouds) can be too faint.
  // We apply a brightness filter to make them more visible while preserving relative colors.
  const isLightMode = mounted && resolvedTheme === "light";

  return (
    <div
      className={cn(
        "relative z-50 -my-1 flex h-6 w-6 items-center justify-center transition-all duration-300 md:h-8 md:w-8",
        isLightMode && "brightness-[0.4] saturate-[1.2]"
      )}
    >
      {animationData ? (
        <Lottie
          animationData={animationData}
          className="h-full w-full"
          loop={true}
        />
      ) : (
        <div className="h-4 w-4 animate-pulse rounded-full bg-muted-foreground/10 capitalize md:h-6 md:w-6" />
      )}
    </div>
  );
}

"use client";

import { createContext, useContext } from "react";

export type CursorType = "default" | "block" | "text";

export interface CursorContextType {
  isHidden: boolean;
  pressing: boolean;
  removeSelectedElement: () => void;
  selectedElement: {
    el: HTMLElement | null;
    type: CursorType;
    config?: Record<string, unknown>;
  };
  setIsHidden: (hidden: boolean) => void;
  setSelectedElement: (element: {
    el: HTMLElement | null;
    type: CursorType;
    config?: Record<string, unknown>;
  }) => void;
  setStatus: (status: string) => void;
  status: string;
}

export const CursorContext = createContext<CursorContextType | null>(null);

const FALLBACK: CursorContextType = {
  isHidden: true,
  pressing: false,
  removeSelectedElement: () => {},
  selectedElement: { el: null, type: "default" },
  setIsHidden: () => {},
  setSelectedElement: () => {},
  setStatus: () => {},
  status: "",
};

export const useCursor = () => {
  const context = useContext(CursorContext);
  if (!context) {
    if (
      process.env.NODE_ENV === "development" &&
      typeof window !== "undefined"
    ) {
      console.warn("useCursor: no CursorProvider found, using inert fallback");
    }
    return FALLBACK;
  }
  return context;
};
